p=np.linspace(0,1,101); q=1000; edge=23-20-.10; pnl=p*q*edge-100; ax.plot(100*p,pnl,color=ACCENT,lw=2); ax.axhline(0,color=INK,lw=.8); ax.axvline(100*(100/(q*edge)),color=BAD,ls='--',lw=1,label='Break-even allocation'); ax.set_xlabel('Allocation probability (%)'); ax.set_ylabel('Expected P&L (USD)'); ax.set_title('IPO allocation is part of the edge',loc='left'); ax.legend(fontsize=7); ax.grid(alpha=.25)
